using System.Drawing;
using System.Windows.Forms;
namespace ZenForms.Core { [ToolboxBitmap(typeof(ToolTip))][System.ComponentModel.Category("ZenForms Modern Components")] public class ZenToolTip:ToolTip { public ZenToolTip(){OwnerDraw=true;BackColor=ZenTheme.SurfaceRaised;ForeColor=ZenTheme.Foreground;InitialDelay=450;ReshowDelay=100;AutoPopDelay=5000;Draw+=DrawTip;Popup+=MeasureTip;} private void MeasureTip(object sender,PopupEventArgs e){e.ToolTipSize=new Size(e.ToolTipSize.Width+12,e.ToolTipSize.Height+8);} private void DrawTip(object sender,DrawToolTipEventArgs e){e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(SolidBrush b=new SolidBrush(ZenTheme.SurfaceRaised))e.Graphics.FillRectangle(b,e.Bounds);using(Pen p=new Pen(ZenTheme.Border))e.Graphics.DrawRectangle(p,e.Bounds.X,e.Bounds.Y,e.Bounds.Width-1,e.Bounds.Height-1);TextRenderer.DrawText(e.Graphics,e.ToolTipText,e.Font,e.Bounds,ZenTheme.Foreground,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);} } }